/**
 * The reading tables: the generated data, and the fallback that uses it.
 *
 * The tables are generated by `tools/build-readings.mjs` from reference
 * implementations, so what is worth testing is not "does the generator run" but
 * two other things:
 *
 *   1. **The table still matches its reference.** A generated file can drift from
 *      the library that produced it, and a wrong romaji is invisible: it looks
 *      like a reading, so nothing about it appears broken.
 *   2. **The fallback covers what the dictionary misses.** The reason this exists
 *      at all is measured: 38% of Korean tokens and 35% of Japanese tokens have no
 *      dictionary entry, so without a fallback they have no reading.
 *
 * Run with `npm test`.
 */

import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { romanize } from 'koroman';
import wanakana from 'wanakana';
import {
  romanizeSyllable,
  romanizeHangul,
  romanizeKana,
  KANA_ROMAJI,
  KANA_CONTRACTED,
  KOREAN_JAMO,
  HANGUL_BASE,
  HANGUL_LAST,
} from '../src/learn/readings.js';

const here = dirname(fileURLToPath(import.meta.url));

let failures = 0;
let checks = 0;

function check(name, actual, expected) {
  checks++;
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a === e) {
    console.log(`  pass  ${name}`);
  } else {
    console.log(`  FAIL  ${name}\n          got      ${a}\n          expected ${e}`);
    failures++;
  }
}

function section(name) {
  console.log(`\n${name}`);
}

section('the Korean jamo tables reproduce the reference for every syllable');

{
  // All 11,172 precomposed syllables, compared against the library the generator
  // derived the tables from. This is the check that makes shipping a table instead
  // of the library safe: if the generator's extraction were wrong, or the table
  // were edited by hand, this fails on the syllable that changed rather than
  // showing a plausible wrong reading.
  const wrong = [];
  let count = 0;
  for (let code = HANGUL_BASE; code <= HANGUL_LAST; code++) {
    const char = String.fromCharCode(code);
    const mine = romanizeSyllable(char);
    const reference = romanize(char);
    count++;
    if (mine !== reference) wrong.push(`${char}: table "${mine}" vs reference "${reference}"`);
  }

  check('every syllable was compared', count, 11172);
  check('and every one matches', wrong.slice(0, 10), []);

  // The tables themselves, so a hand-edit that stays self-consistent is still
  // caught. These are the values a syllable is composed from.
  check('19 initials', KOREAN_JAMO.cho.length, 19);
  check('21 medials', KOREAN_JAMO.jung.length, 21);
  check('28 finals', KOREAN_JAMO.jong.length, 28);
  // ㅇ is SILENT in the initial position, which is why a syllable like 아 is `a`
  // and not `'a`. Getting this wrong would prefix every vowel-initial syllable.
  check('the silent initial is empty', KOREAN_JAMO.cho[11], '');
  check('and a vowel-initial syllable has no leading consonant', romanizeSyllable('아'), 'a');
}

section('the Korean table is right for a syllable and wrong across a boundary');

{
  // **This is why the dictionary is consulted first.** Revised Romanization has
  // sound changes that cross a syllable boundary, and a per-syllable table cannot
  // know them. Asserted rather than documented, because the whole design depends on
  // the ordering being right.
  check('종로 is `jongno` from the entry', romanize('종로'), 'jongno');
  check('but the syllable table gives `jongro`', romanizeHangul('종로'), 'jongro');
  check('신라 is `silla` from the entry', romanize('신라'), 'silla');
  check('but the table gives `sinra`', romanizeHangul('신라'), 'sinra');

  // A LONE syllable has no boundary to cross, so the table is exact. Measured:
  // every missing Korean token in realistic subtitles was a single syllable.
  check('a lone syllable is exact', romanizeHangul('는'), romanize('는'));
  check('and another', romanizeHangul('를'), romanize('를'));

  // Non-Hangul must be refused rather than half-converted, or a mixed run would
  // put romaji beside unchanged characters.
  check('Latin is refused', romanizeHangul('abc'), null);
  check('a mixed run is refused', romanizeHangul('한a'), null);
  check('empty is refused', romanizeHangul(''), null);
}

section('the kana table matches the reference across the shipped corpus');

{
  const japanese = JSON.parse(await readFile(resolve(here, '../src/learn/data/japanese.json'), 'utf8'));
  const readings = Object.values(japanese.words).map((word) => word.p).filter(Boolean);
  const pureKana = readings.filter((reading) => /^[\u3040-\u30ffー]+$/u.test(reading));

  // Where we differ from the reference, and WHY. Pinned rather than allowed, so a
  // new difference is a failure and these stay as the recorded exceptions.
  //
  //   - A reading containing `・` is a pause in an abbreviation (ケー・オー = K.O.).
  //     `romanizeKana` returns null for it because the run is not uniformly kana,
  //     which is the honest answer: half-converting would put a slash inside a
  //     reading.
  //   - A `ー` with no preceding vowel to lengthen (ぼーっと, or a trailing にゃー)
  //     is written by the reference as a literal hyphen or ignored, and we lengthen
  //     the vowel instead, which is the reading a learner expects.
  const documented = { separator: 0, longVowelEdge: 0, other: 0 };
  const other = [];

  for (const reading of pureKana) {
    const mine = romanizeKana(reading);
    const reference = wanakana.toRomaji(reading);
    if (mine === reference) continue;
    if (reading.includes('・')) documented.separator++;
    else if (reading.includes('ー')) documented.longVowelEdge++;
    else {
      documented.other++;
      if (other.length < 10) other.push(`${reading}: table "${mine}" reference "${reference}"`);
    }
  }

  // No undocumented difference at all. This is the assertion that would catch a
  // regression in the sokuon, the contractions or the small kana, each of which was
  // wrong at least once while this was built.
  check('every difference from the reference is a documented kind', other, []);
  check('and there are no other kinds', documented.other, 0);
  // The documented ones are small and countable, so a jump means something changed.
  check('the separator cases', documented.separator, 7);
  check('and the long-vowel edge cases', documented.longVowelEdge, 5);

  // Coverage: a table that omits a kana in the data would silently return null for
  // a word the reader is looking at.
  const missing = new Set();
  for (const reading of readings) {
    for (const char of reading) {
      if (/[\u3040-\u30ff]/u.test(char) && !(char in KANA_ROMAJI) && char !== 'ー' && char !== '・') {
        missing.add(char);
      }
    }
  }
  check('every kana in the corpus has a row', [...missing], []);
}

section('the kana rules that were each wrong once');

{
  // Pinned individually because each was a real bug found by comparing against the
  // reference, and each is invisible: a wrong romaji still looks like a romaji.
  check('a contracted pair', romanizeKana('きゅう'), 'kyuu');
  check('another', romanizeKana('りょこう'), 'ryokou');
  check('and the y-glide', romanizeKana('しゃしん'), 'shashin');
  // ち is `chi`, so ちょ is `cho` and not `chiyo`: the pair lookup has to win over
  // the single rows.
  check('a digraph pair', romanizeKana('ちょっと'), 'chotto');

  // The sokuon doubles the NEXT consonant, so it cannot be a row of its own.
  check('a doubled consonant', romanizeKana('がっこう'), 'gakkou');
  // **Both scripts.** っ and ッ are different code points, and checking only the
  // hiragana one silently failed on every katakana word.
  check('and in katakana', romanizeKana('カッと'), 'katto');
  // A doubled digraph replaces its consonant rather than repeating the letter: ち
  // is `chi` and っち is `tchi`.
  check('a doubled digraph', romanizeKana('ぴったり'), 'pittari');
  check('and inside a contraction', romanizeKana('しょっちゅう'), 'shotchuu');

  // ん has no vowel, so romaji writes an apostrophe before a vowel or y-sound to
  // keep it from reading as a digraph: ぼんやり is not ぼにゃり.
  check('ん before a vowel takes an apostrophe', romanizeKana('ぼんやり'), "bon'yari");
  check('and in katakana', romanizeKana('エックスせん'), 'ekkususen');

  // The long-vowel mark repeats the preceding vowel.
  check('a long vowel', romanizeKana('コーヒー'), 'koohii');
  check('and after a sokuon', romanizeKana('ぼーっと'), 'bootto');

  // Refusal, so a mixed run cannot put half a reading on screen.
  check('kanji is refused', romanizeKana('日本語'), null);
  check('a mixed run is refused', romanizeKana('にほん語'), null);
  check('punctuation is refused', romanizeKana('とても。'), null);
}

section('the fallback covers the tokens the dictionary cannot');

{
  // The measurement that justifies the whole feature. Each of these was a token in
  // realistic subtitles with NO dictionary entry, and therefore no reading before
  // this existed. Korean first.
  const koreanMissing = [
    ['는', 'neun'], ['를', 'reul'], ['가', 'ga'], ['을', 'eul'],
    ['니', 'ni'], ['습', 'seup'], ['합', 'hap'], ['좋', 'jot'],
    ['읽', 'ik'], ['었', 'eot'], ['갔', 'gat'], ['없', 'eop'],
  ];
  const wrongKorean = koreanMissing
    .filter(([text, expected]) => romanizeHangul(text) !== expected)
    .map(([text, expected]) => `${text}: got "${romanizeHangul(text)}", expected "${expected}"`);
  check('every Korean token that had no entry now has a reading', wrongKorean, []);

  // Japanese: the case that looked like it worked. `とても` is kana-only, so the
  // dictionary's kana reading is the word itself, and showing it showed the learner
  // the same string twice. Romaji is the reading that helps here.
  check('a kana-only word has a romaji reading', romanizeKana('とても'), 'totemo');
  check('and a kana ending does', romanizeKana('ませんでした'), 'masendeshita');
  check('and a polite form', romanizeKana('ございます'), 'gozaimasu');

  // Chinese gets no fallback, and the reason is measured rather than assumed: a
  // hanzi's reading is lexical and context dependent, so a table would be wrong
  // about half the time. 阿姨 is `āyí`, not `yí`.
  check('there is no hanzi table, on purpose', KANA_ROMAJI['あ'] !== undefined && !KANA_ROMAJI['我'], true);
}

console.log(`\n${checks - failures}/${checks} checks passed`);
process.exit(failures === 0 ? 0 : 1);
